export const getUser = (id) => fetch("/api/v1/users/" + id, { method: "GET" });
export const listOrders = () => fetch("/api/v1/orders?page=1&size=20");
export const exportAll = () => fetch("/api/v1/admin/export", { method: "POST" });
export const dropReport = (id) => fetch("/api/v2/reports/" + id, { method: "DELETE" });
